const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(action,label,index,pressed=false)=>`<button type="button" data-x="p34-${action}"${index===undefined?'':` data-index="${esc(index)}"`} aria-pressed="${!!pressed}">${esc(label)}</button>`;
const input=(key,label,value,placeholder='')=>`<label class="p34-field"><span>${esc(label)}</span><input data-xfield="${esc(key)}" value="${esc(value)}" placeholder="${esc(placeholder)}" autocomplete="off"></label>`;
const select=(key,label,value,options)=>`<label class="p34-field"><span>${esc(label)}</span><select data-xfield="${esc(key)}"><option value="">选择</option>${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
const symbol=(t,id)=>{const x=t.symbols.find(x=>x.id===id);return `<span class="p34-symbol" style="--symbol-color:${esc(x?.color||'#78978c')}">${esc(x?.mark||'?')}<small>${esc(x?.name||'')}</small></span>`;};
const chips=xs=>`<div class="p34-row">${xs.map(x=>`<span class="p34-chip">${esc(x)}</span>`).join('<b class="p34-arrow">→</b>')}</div>`;
function repeating(t,b){return `<div class="p34-label">${t.mode==='own'?'自己搭的图案':'已经有的图案'}</div><div class="p34-shapes">${[...(t.seed||[]),...b.added].map(id=>symbol(t,id)).join('')}${b.added.length<t.need?'<span class="p34-blank">?</span>':''}</div>`;}
function sequence(t,b){return `<div class="p34-label">${esc(t.sceneLabel||'把每一步留下')}</div>${chips(b.values.map(n=>String(n/(t.scale||1))))}`;}
function pair(t,b){const rows=b.pairs.map(([x,y],i)=>`<div><b>第${i+1}组</b><span>${x}</span><span>${y}</span></div>`).join('');let grid='';if(t.plot&&b.pairs.length===t.length){const cell=(x,y)=>{const active=b.plotted.some(p=>p[0]===(t.sx||0)+x*t.dx&&p[1]===(t.sy||0)+y*t.dy);return `<button type="button" data-x="p34-plot" data-index="${x},${y}" aria-label="横${(t.sx||0)+x*t.dx}，纵${(t.sy||0)+y*t.dy}" aria-pressed="${active}">${active?'●':''}</button>`;};grid=`<div class="p34-gridwrap"><div class="p34-axis">纵向：第二列</div><div class="p34-coordinate"><span></span>${Array.from({length:t.length},(_,x)=>`<strong>${(t.sx||0)+x*t.dx}</strong>`).join('')}${Array.from({length:t.length},(_,j)=>{const y=t.length-1-j;return `<strong>${(t.sy||0)+y*t.dy}</strong>${Array.from({length:t.length},(_,x)=>cell(x,y)).join('')}`;}).join('')}</div><div class="p34-axis">横向：第一列</div></div>`;}
 return `<div class="p34-label">两条规则，各从自己的起点开始</div><div class="p34-pairs"><div><b>位置</b><b>第一列</b><b>第二列</b></div>${rows}</div>${grid}`;}
function ambiguity(t,b){return `<div class="p34-label">两条机器都有同样的开头</div>${chips([2,4,6,'?'])}${b.prediction!==null?`<p>刚才的猜想：${esc(b.prediction)}</p>`:''}${b.shown.includes('a')?`<div class="p34-result">规则A：每次加2　→　2、4、6、<b>8</b></div>`:''}${b.shown.includes('b')?`<div class="p34-result">规则B：加2、加2、加4循环　→　2、4、6、<b>10</b></div>`:''}`;}
function grid(t,b){return `<div class="p34-label">每一格是一种搭配</div><div class="p34-pairgrid" style="--p34-cols:${t.cols.length+1}"><span></span>${t.cols.map(x=>`<strong>${esc(x)}</strong>`).join('')}${t.rows.map((r,i)=>`<strong>${esc(r)}</strong>${t.cols.map((c,j)=>btn('cell',b.selected.includes(i*t.cols.length+j)?'✓':'＋',i*t.cols.length+j,b.selected.includes(i*t.cols.length+j))).join('')}`).join('')}</div>`;}
const groups={both:'3和5都符合',three:'只符合3',five:'只符合5',neither:'都不符合',unknown:'未分类'};
function program(t,b){let body='';if(['walk','double','add7'].includes(t.mode))body=chips(b.values);else if(['threshold','sort10'].includes(t.mode)){const n=t.inputs[b.records.length];body=`<div class="p34-current">${n===undefined?'这一组处理完了':`现在是 ${n}`}</div><div class="p34-records">${b.records.map(x=>`<span>${x.n} → ${esc(t.mode==='sort10'?(x.out==='low'?'小于10':'10或更多'):x.out)}</span>`).join('')}</div>`;}else{const last=b.runs.at(-1);body=`<div class="p34-label">已排的步骤</div>${chips(b.blocks.map(id=>t.blocks.find(x=>x.id===id)?.label||id))}`;if(last&&JSON.stringify(last.blocks)!==JSON.stringify(b.blocks)){body+='<p>步骤已改，重新运行。</p>';}else if(last){if(t.mode==='loop')body+=`<div class="p34-label">起点和10次新结果</div>${chips(last.output)}`;else{const hit=last.output.find(x=>x.n===15);body+=`<p>15 被放在：<b>${esc(groups[hit?.group])}</b></p><details><summary>展开30个数的结果</summary><div class="p34-records">${last.output.map(x=>`<span>${x.n}：${esc(groups[x.group])}</span>`).join('')}</div></details>`;}}}return `<div class="p34-label">${esc(t.sceneLabel||'按步骤往前走')}</div>${body}${b.done?'<div class="p34-done">这次走到了停止处。</div>':''}`;}
export function visual(t,m){const b=m.board,v=t.type==='x-p34-repeat'?repeating(t,b):t.type==='x-p34-sequence'?sequence(t,b):t.type==='x-p34-pair'?pair(t,b):t.type==='x-p34-ambiguity'?ambiguity(t,b):t.type==='x-p34-grid'?grid(t,b):t.type==='x-p34-relation'?`<div class="p34-label">选出的等值写法</div>${chips(b.selected.map(i=>t.cards[i].label))}`:t.type==='x-p34-program'?program(t,b):'';return `<div class="p34-world">${v}</div>`;}
export function controls(t,m){const b=m.board;let s='<div class="p34-controls">';
 if(t.type==='x-p34-repeat')s+=`<div class="p34-buttons">${t.symbols.map(x=>btn('pick',x.mark+' '+x.name,x.id)).join('')}</div>${btn('undo','拿回最后一块')}${btn('clear','重新摆')}`;
 if(t.type==='x-p34-sequence'&&b.values.length<t.length)s+=input('value','下一项',m.value,'写一个数')+btn('next','放到后面')+btn('undo','退回一步');
 if(t.type==='x-p34-pair'){if(b.pairs.length<t.length)s+=input('value','第一列下一项',m.value)+input('second','第二列下一项',m.second)+btn('next','留下这一对');else if(t.plot)s+='<p>把每一对数放到图上的对应位置。</p>';}
 if(t.type==='x-p34-ambiguity'){if(b.prediction===null)s+=input('value','你猜下一项',m.value)+btn('predict','记下猜想');else s+=`<div class="p34-buttons">${btn('show','试规则A','a',b.shown.includes('a'))}${btn('show','试规则B','b',b.shown.includes('b'))}</div>`;}
 if(t.type==='x-p34-grid')s+='<p>点格子配成一对；再点一次可以拿回。</p>';
 if(t.type==='x-p34-relation')s+=`<div class="p34-buttons">${t.cards.map((x,i)=>btn('cell',x.label,i,b.selected.includes(i))).join('')}</div>`;
 if(t.type==='x-p34-growth')s+=`<div class="p34-growth-labels">${t.known.map((n,i)=>`<span>第${i+1}组：${n}块</span>`).join('')}<span>第4组：${b.filled.length}块</span></div><div class="p34-buttons">${btn('fill','放一块')}${btn('turn','转一转')}</div><p>可以点空间里的空位放块，也可以拖动转动视角。</p>`;
 if(t.type==='x-p34-program'){
  if(t.mode==='walk'&&!b.done)s+=`<div class="p34-buttons">${btn('step','偶数：减半','half')}${btn('step','奇数：加1','plus')}</div>`;
  if(t.mode==='threshold'&&!b.done)s+=`<div class="p34-buttons">${btn('branch','大于50：减10','yes')}${btn('branch','不大于50：加10','no')}</div>`;
  if(t.mode==='sort10'&&!b.done)s+=`<div class="p34-buttons">${btn('branch','小于10','low')}${btn('branch','10或更多','high')}</div>`;
  if(['double','add7'].includes(t.mode)&&!b.done)s+=`<div class="p34-buttons">${btn('step',t.mode==='double'?'翻倍':'再加7')}${btn('stop','停在这里')}</div>`;
  if(['classify','loop'].includes(t.mode))s+=`<div class="p34-buttons">${t.blocks.map(x=>btn('block',x.label,x.id,b.blocks.includes(x.id))).join('')}${btn('undo','退回一步')}${btn('clear','重新排')}${btn('run','运行看看')}</div>`;
 }
 const ready=t.type!=='x-p34-ambiguity'||b.shown.length===2;
 if(ready)for(const[i,q]of(t.questions||[]).entries())s+=q.options?select('answers.'+i,q.label,m.answers[i],q.options):input('answers.'+i,q.label,m.answers[i]);
 if(m.issue)s+=`<p class="p34-issue" role="status">${esc(m.issue)}</p>`;
 return s+`<details><summary>留下自己的想法（可选）</summary>${input('prose','我的解释或新问题',m.prose)}<small>原话会保存，暂不自动判断。</small></details></div>`;
}
export const render=(t,m)=>t.type==='x-p34-growth'?`<div id="extra-world" class="cube-world p34-space"></div><div id="extra-controls">${controls(t,m)}</div>`:`<div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}</div>`;
